import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"交换机架构与背板","description":"","frontmatter":{"title":"交换机架构与背板","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/switch-fabric.md","filePath":"cs/switch-fabric.md","lastUpdated":1789023840000}'),h={name:"cs/switch-fabric.md"};function A(u,a,E,P,_,m){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="交换机架构与背板" tabindex="-1">交换机架构与背板 <a class="header-anchor" href="#交换机架构与背板" aria-label="Permalink to &quot;交换机架构与背板&quot;">​</a></h1><div class="epigraph"><p>线速转发要把所有口的峰值同时搬过一块交换结构；结构容量、内部阻塞与 CPU 慢路径决定「交换」是芯片还是总线。</p><footer>—— 据 Karol, Hluchyj and Morgan, Input Versus Output Queueing, IEEE Trans. Commun. 1987；交换结构综述整理</footer></div><p><a href="/cs/mac-learning">上一课</a>把转发说成查表出端口。缺口是<strong>包如何从入端口内存走到出端口</strong>：共享总线、共享内存、交叉开关、Clos 片上网络。本课不把队头阻塞定理写完，只点名结构。下一课专讲 HOL。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(N\\) 个口各 \\(R\\) b/s，无阻塞结构需要约 \\(N R\\) 的内部带宽（再加头税）。低端设备用 CPU 加软件桥（慢路径）；线速盒用 ASIC：解析 → 查 MAC/ACL → 过 fabric → 出口队列。控制面（STP、LLDP、LACP）上送 CPU，与数据面分离。过订购（oversubscription）把结构做得小于 \\(N R\\)，瞬时全口对打会丢——这是产品规格，不是 MAC 学习失败。</p><p><span class="marginnote">「背板带宽」常被营销加总双向。看无阻塞与否要比看一个更大的数字重要。本课不点名具体型号。</span></p><h3 id="线速是结构承诺" tabindex="-1">线速是结构承诺 <a class="header-anchor" href="#线速是结构承诺" aria-label="Permalink to &quot;线速是结构承诺&quot;">​</a></h3><p>过订购会在内部丢，不是学习失败。控制面 CPU 处理慢协议，数据面 ASIC 走热路径。背板营销数字要问是否无阻塞。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三种：共享总线（一时刻一帧）、共享内存（写中央、读出口）、交叉开关（VOQ 对付 HOL）。画包路径：PHY → MAC → 入队/解析 → fabric → 出队 → PHY。PFC 阈值设在这些队列上。</p>',10)),(e(),n(d,null,{default:r(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%85%A5%E7%AB%AF%E5%8F%A3%22%5D%20--%3E%20PAR%5B%22%E8%A7%A3%E6%9E%90%E4%B8%8E%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20PAR%20--%3E%20FAB%5B%22%E4%BA%A4%E6%8D%A2%E7%BB%93%E6%9E%84%22%5D%0A%20%20FAB%20--%3E%20OQ%5B%22%E5%87%BA%E7%AB%AF%E5%8F%A3%E9%98%9F%E5%88%97%22%5D%0A%20%20CPU%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%20CPU%22%5D%20-.-%3E%20PAR%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>速率演进加 lane，结构必须跟上。LACP 哈希在入或出完成，结构仍看到多个物理口或已聚合的逻辑带宽。巨帧占用结构更长时间，小包 PPS 打满查表。主干分层：结构不改以太网语义，只决定能否线速实现语义。</p><p>慢路径：未知控制协议、异常 TTL 不算这里（那是路由器），二层盒上送 BPDU/LLDP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入芯片内部的 replay 缓冲细节。输出排队与 HOL 是下一课。后课默认：线速 = 结构与查表匹配口速；过订购会在内部丢。</p><p>不要把「交换机很智能」写成应用层负载均衡——那是后课 L4/L7。</p><p>上一课留下的缺口在本课收口；「交换机架构与背板」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/output-queue-hol">输出排队与 HOL</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无阻塞结构带宽必须跟上 Σ 口速。</li><li>数据面 ASIC 与控制面 CPU 分工。</li><li>过订购表现为内部丢包。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Karol et al., 1987；交换结构通识。</li></ul>',10))])}const b=o(h,[["render",A]]);export{C as __pageData,b as default};
